"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Headless terminal display backed by xterm.js. Renders an xterm grid
 * inside a div the consumer styles. No PTY, no shell — the consumer
 * owns the data-flow:
 *
 *   - Pass `output` (string or string[]) to write to the display. Each
 *     change is diffed against the prior render and only the new tail
 *     is `term.write()`-ed, so feeding a streaming buffer doesn't redraw.
 *   - Pass `onInput` to receive bytes the user typed. Wire it to a
 *     WebSocket / IPC / fetch stream — terminal doesn't care.
 *
 * Heavy peer: requires `@xterm/xterm` (~150 KB gzip). The hex-core CLI's
 * `add` flow prompts before installing.
 *
 * @example
 * <Terminal
 *   output={["$ ls\r\n", "package.json  src/\r\n", "$ "]}
 *   onInput={(data) => ws.send(data)}
 *   rows={24}
 *   cols={80}
 * />
 */
export interface TerminalProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children" | "onInput"> {
	/**
	 * Bytes to display. String is written verbatim; string[] is joined.
	 * On change, only the suffix beyond the prior render is emitted, so
	 * appending to a streaming buffer is O(delta).
	 */
	output?: string | string[];
	/** Receive bytes the user typed (incl. control sequences). */
	onInput?: (data: string) => void;
	/** Initial cols. xterm allows runtime resize via fit-addon (not bundled). Default 80. */
	cols?: number;
	/** Initial rows. Default 24. */
	rows?: number;
	/** Theme tokens — defaults to neutral light/dark via CSS vars. */
	theme?: "dark" | "light";
	/** Enable cursor blink. Default true. */
	cursorBlink?: boolean;
	/** Whether the user can type into the terminal. Default true. */
	disableInput?: boolean;
}

const DARK_THEME = {
	background: "#0a0a0a",
	foreground: "#e5e5e5",
	cursor: "#e5e5e5",
	selectionBackground: "#404040",
};
const LIGHT_THEME = {
	background: "#fafafa",
	foreground: "#171717",
	cursor: "#171717",
	selectionBackground: "#d4d4d4",
};

/**
 * Renders an xterm.js terminal display.
 * @param props - Terminal output + input handler + display options
 * @returns A div containing the xterm grid
 */
function Terminal({
	output,
	onInput,
	cols = 80,
	rows = 24,
	theme = "dark",
	cursorBlink = true,
	disableInput = false,
	className,
	...rest
}: TerminalProps) {
	const containerRef = React.useRef<HTMLDivElement | null>(null);
	const termRef = React.useRef<import("@xterm/xterm").Terminal | null>(null);
	const writtenRef = React.useRef<string>("");
	const onInputRef = React.useRef(onInput);
	onInputRef.current = onInput;

	const initialOutput = React.useMemo(
		() => normalizeOutput(output),
		// initial-only: subsequent diffs are handled by the output effect.
		[],
	);

	// Initialize xterm once on mount. Dynamic import keeps the engine out
	// of consumers' bundles unless they actually mount the component.
	React.useEffect(() => {
		if (!containerRef.current) return;

		let disposed = false;
		let inputDispose: { dispose: () => void } | null = null;

		void (async () => {
			const xtermModule = await import("@xterm/xterm");
			if (disposed || !containerRef.current) return;

			const term = new xtermModule.Terminal({
				cols,
				rows,
				cursorBlink,
				disableStdin: disableInput,
				theme: theme === "dark" ? DARK_THEME : LIGHT_THEME,
				fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
				fontSize: 13,
			});
			term.open(containerRef.current);
			termRef.current = term;

			if (initialOutput) {
				term.write(initialOutput);
				writtenRef.current = initialOutput;
			}

			inputDispose = term.onData((data) => {
				onInputRef.current?.(data);
			});
		})();

		return () => {
			disposed = true;
			inputDispose?.dispose();
			termRef.current?.dispose();
			termRef.current = null;
			writtenRef.current = "";
		};
		// cols/rows/theme/cursorBlink/disableInput are mount-time options.
		// Changing them mid-session would force a full re-init that'd lose
		// scrollback — out of scope for v1.
	}, []);

	// Diff `output` against what's already on screen and write only the new tail.
	React.useEffect(() => {
		const term = termRef.current;
		if (!term) return;
		const next = normalizeOutput(output);
		if (next === writtenRef.current) return;
		if (next.startsWith(writtenRef.current)) {
			const delta = next.slice(writtenRef.current.length);
			if (delta) term.write(delta);
		} else {
			// Non-suffix change (e.g. consumer cleared the buffer or replaced it
			// with unrelated content) — reset the screen and write fresh.
			term.reset();
			if (next) term.write(next);
		}
		writtenRef.current = next;
	}, [output]);

	return (
		<div
			{...rest}
			ref={containerRef}
			data-hex-terminal
			data-theme={theme}
			className={cn(
				"overflow-hidden rounded-md border bg-background p-2",
				"font-mono text-sm leading-tight",
				className,
			)}
		/>
	);
}

function normalizeOutput(value: string | string[] | undefined): string {
	if (value == null) return "";
	return Array.isArray(value) ? value.join("") : value;
}

export { Terminal };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

